// [Blur2PC][macOS] Original upper Context/Device coverage state, actual per-sample GPU output.
#include <display.h>
#include <display/context/Context.h>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
static void require(bool value,const char* why){if(!value)throw std::runtime_error(why);}
template<class F>static void rejects(F f,const char* why){bool rejected=false;try{f();}catch(const std::logic_error&){rejected=true;}require(rejected,why);}
static std::vector<U8> blob(bool vertex){
    const std::string metadata=vertex?R"({"parameters":{},"input_semantics":[],"reflection":{"ubos":[]}})":R"({"parameters":{},"input_semantics":[],"reflection":{"ubos":[{"binding":0,"block_size":16,"name":"Colour"},{"binding":1,"block_size":16,"name":"BlurPCAlphaTestState"}]}})";
    const std::string source=std::string("#include <metal_stdlib>\nusing namespace metal;\n")+(vertex?
        "struct V{float4 p[[position]];};vertex V blur_main(uint i[[vertex_id]]){const float2 p[3]={float2(-1,-1),float2(3,-1),float2(-1,3)};return {float4(p[i],.25,1)};}":
        "struct O{float4 a[[color(0)]];float4 b[[color(1)]];};struct A{uint enabled;uint function;float reference;uint format;};fragment O blur_main(constant float4& c[[buffer(0)]],constant A& a[[buffer(1)]]){if(a.enabled&&c.w<=a.reference)discard_fragment();return {c,float4(0,1,0,1-c.w)};}");
    const std::string entry="blur_main";std::vector<U8> result(40);auto word=[&](U32 at,U32 value){for(U32 i=0;i<4;++i)result[at+i]=U8(value>>(i*8));};std::memcpy(result.data(),"BMSL",4);word(4,1);word(8,vertex?0:1);word(16,40);word(20,metadata.size());word(24,40+metadata.size());word(28,source.size());word(32,40+metadata.size()+source.size());word(36,entry.size());result.insert(result.end(),metadata.begin(),metadata.end());result.insert(result.end(),source.begin(),source.end());result.insert(result.end(),entry.begin(),entry.end());word(12,result.size());return result;
}
static std::vector<U32> pixels(const Display::C_RenderTexture2D& target){auto p=target.GetTexture().LockRect2D(0,16);require(p.pBits,"Actual coverage resolve readback failed");std::vector<U32> result(target.GetTexture().GetWidth()*target.GetTexture().GetHeight());for(U32 y=0;y<target.GetTexture().GetHeight();++y)std::memcpy(result.data()+y*target.GetTexture().GetWidth(),p.pBits+y*p.pitch,target.GetTexture().GetWidth()*4);target.GetTexture().UnlockRect2D(0);return result;}
struct Resources{
    Display::C_Device& device;Display::C_VertexShader vs;Display::C_PixelShader ps;Display::C_VertexDeclaration declaration;Display::C_RenderTexture2D colour,second;Display::C_Surface depth;bool active=false;
    void Begin(){device.GetDisplay2().GetContext().BeginScene();active=true;}
    void End(){device.GetDisplay2().GetContext().EndScene();active=false;}
    ~Resources(){if(active)End();device.GetDisplay2().GetContext().SetColourSurface(1,nullptr);device.SetColourDepthStencilSurface();device.SetVertexShader(nullptr);device.SetPixelShader(nullptr);device.SetVertexDeclaration(nullptr);device.Destroy(&colour);device.Destroy(&second);device.Destroy(&depth);device.GetDisplay2().Destroy(&declaration);device.Destroy(&ps);device.Destroy(&vs);}
};
static void check(Display::C_Device& device,Display::E_Multisample samples){
    using namespace Display;Resources owner{device};auto& lower=device.GetDisplay2().GetContext();C_Context upper;upper.m_Context.Bind(device.GetDisplay2());
    auto v=blob(true),p=blob(false);require(device.CreateVertexShader(v.size(),reinterpret_cast<const S32*>(v.data()),0,&owner.vs)&&device.CreatePixelShader(p.size(),reinterpret_cast<const S32*>(p.data()),0,&owner.ps),device.GetNativeError().c_str());
    Display2::C_VertexFormat format;format.AddElement(0,0,Display2::E_VertexElementType_F32_2,Display2::E_VertexElementUsage_Position,0);require(device.GetDisplay2().CreateVertexDeclaration(format,&owner.declaration),"Coverage declaration allocation failed");
    require(device.CreateRenderTexture2D(32,32,1,E_Usage_Colour,E_Format_A8R8G8B8,samples,nullptr,&owner.colour)&&device.CreateRenderTexture2D(32,32,1,E_Usage_Colour,E_Format_A8R8G8B8,samples,nullptr,&owner.second)&&device.CreateDepthStencilSurface(32,32,E_Usage_DepthStencil,E_Format_D24S8,samples,nullptr,&owner.depth),"Coverage MRT/depth targets failed");
    auto setup=[&]{device.SetColourDepthStencilSurface(&owner.colour.GetSurface(),&owner.depth);device.SetColourSurface(1,&owner.second.GetSurface());device.SetVertexShader(&owner.vs);device.SetPixelShader(&owner.ps);device.SetVertexDeclaration(&owner.declaration);device.SetAlphaTestEnable(E_Bool_False);device.SetDepthEnable(E_Bool_False);device.SetDepthWriteEnable(E_Bool_False);device.SetStencilEnable(E_Bool_False);device.SetColourWriteEnable(E_ColourWriteEnable_All);device.SetBlendEnable(E_Bool_False);device.SetCullMode(E_CullMode_None);C_Viewport viewport;viewport.m_W=viewport.m_H=32;device.SetViewport(viewport);};
    auto colour=[&](F32 alpha){const F32 c[]={1,0,0,alpha};device.SetPixelShaderConstantF(0,c,1);};
    auto draw=[&](F32 alpha,bool coverage,bool contextRoute,bool alphaTest=false,bool blend=false){owner.Begin();setup();if(contextRoute)upper.SetAlphaToMaskEnable(coverage?E_Bool_True:E_Bool_False);else device.SetAlphaToMaskEnable(coverage?E_Bool_True:E_Bool_False);device.SetAlphaTestEnable(alphaTest?E_Bool_True:E_Bool_False);device.SetAlphaTestFunc(E_CmpFunc_Greater);device.SetAlphaTestRef(200);device.SetBlendEnable(blend?E_Bool_True:E_Bool_False);device.SetBlendSrc(E_Blend_SrcAlpha);device.SetBlendDst(E_Blend_InvSrcAlpha);device.SetBlendSrcAlpha(E_Blend_One);device.SetBlendDstAlpha(E_Blend_Zero);device.Clear(E_Clear_Colour,Maths::RGBA(0));colour(alpha);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);owner.End();return pixels(owner.colour);};
    std::vector<double> coverage;
    for(F32 alpha:{0.f,.25f,.5f,.75f,1.f}){
        auto actual=draw(alpha,true,true),other=pixels(owner.second);double total=0;
        for(U32 i=0;i<actual.size();++i){const U32 red=actual[i]>>16&255,green=other[i]>>8&255;require(std::abs(S32(red)-S32(green))<=1,"MRT coverage did not use output0 alpha for every target");require(!(actual[i]&0xffff)&&!(other[i]&0xff00ff),"Coverage changed unrelated colour channels");if(std::abs(F32(actual[i]>>24)-red*alpha)>1.1f){std::cerr<<"alpha mismatch samples="<<U32(samples)<<" alpha="<<alpha<<" pixel="<<i<<" value0=0x"<<std::hex<<actual[i]<<" value1=0x"<<other[i]<<std::dec<<" red="<<red<<" expectedA="<<red*alpha<<std::endl;throw std::runtime_error("Alpha-to-one altered the original PC shader alpha");}if(alpha==0)require(!actual[i]&&!other[i],"Zero alpha retained covered samples");if(alpha==1)require(red==255&&green==255,"One alpha lost covered samples");if(samples==E_Multisample_None)require(red==0||red==255,"Single-sample output was blended instead of masked");total+=red/255.;}
        coverage.push_back(total/actual.size());
    }
    for(U32 i=1;i<coverage.size();++i)require(coverage[i]>=coverage[i-1],"Alpha coverage decreased as alpha increased");if(samples!=E_Multisample_None)require(coverage[2]>.1&&coverage[2]<.9,"MSAA alpha did not produce partial sample coverage");
    const auto half=draw(.5f,true,true);require(draw(.5f,true,false)==half,"Device and Context coverage policies disagree");
    const auto disabled=draw(0,false,false);for(U32 value:disabled)require(value==0x00ff0000,"Disabling coverage left a cached coverage pipeline active");require(draw(.5f,true,true)==half,"Re-enabling coverage did not restore its original pipeline");
    const auto tested=draw(.5f,true,true,true);for(U32 value:tested)require(value==0,"Independent alpha testing stopped rejecting fragments");
    const auto blended=draw(.5f,true,true,false,true);for(U32 i=0;i<half.size();++i)require(std::abs(S32(blended[i]>>16&255)-S32(half[i]>>16&255)*.5f)<=1.1f,"Coverage and colour blending were conflated");
    // Coverage must gate real depth/stencil sample updates as well as both colour attachments.
    owner.Begin();setup();upper.SetAlphaToMaskEnable(E_Bool_True);device.SetDepthEnable(E_Bool_True);device.SetDepthWriteEnable(E_Bool_True);device.SetDepthFunc(E_CmpFunc_Less);
    Display2::C_StencilState stencil;stencil.SetStencilFunc(Display2::E_CmpFunc_Always);stencil.SetStencilRef(7);stencil.SetStencilMask(255);stencil.SetStencilWriteMask(255);stencil.SetStencilDepthPass(Display2::E_StencilOp_Replace);lower.SetStencilState(stencil);device.SetStencilEnable(E_Bool_True);
    device.Clear(E_Clear_Colour|E_Clear_Depth|E_Clear_Stencil,Maths::RGBA(0),1,0);colour(.5f);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);owner.End();require(pixels(owner.colour)==half,"Depth/stencil configuration changed colour coverage");
    owner.Begin();setup();upper.SetAlphaToMaskEnable(E_Bool_False);stencil.SetStencilFunc(Display2::E_CmpFunc_Equal);stencil.SetStencilWriteMask(0);stencil.SetStencilDepthPass(Display2::E_StencilOp_Keep);lower.SetStencilState(stencil);device.SetStencilEnable(E_Bool_True);device.Clear(E_Clear_Colour,Maths::RGBA(0));colour(1);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);owner.End();auto stencilPixels=pixels(owner.colour);for(U32 i=0;i<half.size();++i)require((stencilPixels[i]&0xffffff)==(half[i]&0xffffff),"Alpha coverage did not gate actual stencil sample writes");
    owner.Begin();setup();device.SetDepthEnable(E_Bool_True);device.SetDepthWriteEnable(E_Bool_False);device.SetDepthFunc(E_CmpFunc_Less);device.Clear(E_Clear_Colour,Maths::RGBA(0));const F32 green[]={0,1,0,1};device.SetPixelShaderConstantF(0,green,1);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);owner.End();auto depthPixels=pixels(owner.colour);for(U32 i=0;i<half.size();++i)require(std::abs(S32(depthPixels[i]>>8&255)+S32(half[i]>>16&255)-255)<=1,"Alpha coverage did not gate actual depth sample writes");
    // Mid-scene invalid requests cannot mutate the previous valid coverage state.
    owner.Begin();setup();upper.SetAlphaToMaskEnable(E_Bool_True);rejects([&]{upper.SetAlphaToMaskEnable(E_Bool_Unknown);},"Unknown context coverage boolean accepted");rejects([&]{device.SetAlphaToMaskEnable(E_Bool_Unknown);},"Unknown device coverage boolean accepted");rejects([&]{lower.SetAlphaToMaskEnable(Display2::E_Bool_Unknown);},"Unknown lower coverage boolean accepted");device.Clear(E_Clear_Colour,Maths::RGBA(0));colour(.5f);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);
    // A partial clear uses a separate internal pipeline and must neither mask the clear nor change requested coverage.
    C_Viewport small;small.m_X=3;small.m_Y=5;small.m_W=7;small.m_H=9;device.SetViewport(small);device.Clear(E_Clear_Colour,Maths::RGBA(0x00123456));owner.End();auto cleared=pixels(owner.colour);for(U32 y=0;y<32;++y)for(U32 x=0;x<32;++x)require(cleared[y*32+x]==(x>=3&&x<10&&y>=5&&y<14?0x00123456:half[y*32+x]),"Partial clear inherited coverage or altered pixels outside its viewport");
    owner.Begin();setup();device.Clear(E_Clear_Colour,Maths::RGBA(0));colour(.5f);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);owner.End();require(pixels(owner.colour)==half,"Internal clear pipeline changed requested alpha coverage");
    // Frame defaults retire both the lower coverage request and the upper device cache.
    device.DefaultStates();owner.Begin();setup();device.Clear(E_Clear_Colour,Maths::RGBA(0));colour(0);lower.DrawPrimitive(Display2::E_PrimitiveType_TriangleList,0,3);owner.End();for(U32 value:pixels(owner.colour))require(value==0x00ff0000,"DefaultStates retained alpha coverage from a previous frame");
    std::cout<<"samples="<<U32(samples)<<" alpha coverage=";for(auto n:coverage)std::cout<<n<<',';std::cout<<'\n';
}
int main(){try{Display::C_Device device;Display::C_DeviceParams params;params.m_Width=params.m_Height=32;require(device.Create(params)&&device.CreateVolatile(params),"Upper native device creation failed");try{for(auto samples:{Display::E_Multisample_None,Display::E_Multisample_2,Display::E_Multisample_4,Display::E_Multisample_None})check(device,samples);}catch(...){device.DestroyVolatile();device.Destroy();throw;}require(device.GetDisplay2().WaitIdle(),"Coverage GPU command failed");device.DestroyVolatile();device.Destroy();std::cout<<"Original PC alpha-to-coverage upper Context/Device, 1x/2x/4x MRT masks/alpha, independent blend/test, clear/default/rebind pipeline transitions and invalid-state retry PASS\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
